import json, sys

path = sys.argv[1] if len(sys.argv) > 1 else ".coordination/B-work/swagger-docs/r6-api-docs.json"
doc = json.load(open(path))
schemas = doc.get("components", {}).get("schemas", {})

# Scan exactly like the Java scanStructure would: start at each schema root,
# recurse into properties.*, items, additionalProperties.
hits = []


def scan(node, p, is_root=False):
    if not isinstance(node, dict):
        return
    if "$ref" in node:
        return
    # record typeless nodes (no type key) that are not $ref
    if "type" not in node:
        # exclude nodes that are just wrappers? record all typeless non-ref
        hits.append((p, json.dumps(node, ensure_ascii=False)[:200]))
    props = node.get("properties")
    if isinstance(props, dict):
        for k, v in props.items():
            scan(v, p + "." + k)
    if node.get("type") == "array":
        scan(node.get("items"), p + "[]")
    ap = node.get("additionalProperties")
    if isinstance(ap, dict):
        scan(ap, p + ".*")


for name, schema in schemas.items():
    scan(schema, name, is_root=True)

for p, s in hits:
    print(p)
    print("   ", s)
print("TOTAL", len(hits))

