    if isinstance(node, dict):
        r=node.get("$ref")
        if isinstance(r,str):
            n=r.rsplit("/",1)[-1]
            if n not in out:
                out.add(n); queue.append(n)
        for v in node.values(): refs(v,out,queue)
    elif isinstance(node,list):
        for v in node: refs(v,out,queue)

